def run():
    app = create_app("development")
    with app.app_context():
        added = 0
        updated = 0
        for entry in SCHOLARSHIPS:
            existing = Scholarship.query.filter_by(
                source_name="full_seed", external_id=entry["external_id"]
            ).first()
            if existing:
                for key, value in entry.items():
                    setattr(existing, key, value)
                updated += 1
            else:
                db.session.add(Scholarship(source_name="full_seed", **entry))
                added += 1
        db.session.commit()
        total = Scholarship.query.count()
        print(f"Done! {added} added, {updated} updated.")
        print(f"Total scholarships now in database: {total}")


if __name__ == "__main__":
    run()
